        "testata": "BBC News",
        "lingua_originale": "en",
        "titolo_orig": "Lebanon and Israel officials to meet in US on Tuesday",
        "testo_it": "Gli ambasciatori di Israele e Libano negli USA si incontreranno a Washington per colloqui diplomatici.",
        "priorita": "Alta",
        "id_gruppo": 6,
        "link": "https://www.bbc.com/news/articles/c93en5q2zl3o?at_medium=RSS&at_campaign=rss",
